-- v010: tutor feedback activity must not change the displayed latest music receipt time.
create or replace function public.nadi_planner_read(p_learner_id uuid) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$ begin
 if auth.uid() is null or not exists(select 1 from public.nadi_profiles where id=auth.uid()) or p_learner_id is null or not coalesce(public.nadi_can_read(p_learner_id),false) then raise exception 'Denied' using errcode='42501'; end if;
 return jsonb_build_object('goals',coalesce((select jsonb_agg(to_jsonb(g)||jsonb_build_object('steps',coalesce((select jsonb_agg(to_jsonb(s) order by s.position,s.id) from public.nadi_goal_steps s where s.goal_id=g.id),'[]'::jsonb),'reviews',coalesce((select jsonb_agg(to_jsonb(v)||jsonb_build_object('revision',r.revision) order by v.created_at desc,v.id) from public.nadi_goal_reviews v join public.nadi_revisions r on r.id=v.snapshot_id where v.goal_id=g.id),'[]'::jsonb),'review',(select to_jsonb(v)||jsonb_build_object('revision',r.revision) from public.nadi_goal_reviews v join public.nadi_revisions r on r.id=v.snapshot_id where v.goal_id=g.id order by v.created_at desc,v.id limit 1)) order by g.due_date nulls last,g.created_at desc) from public.nadi_goals g where g.learner_id=p_learner_id),'[]'::jsonb),'projects',coalesce((select jsonb_agg(jsonb_build_object('projectId',p.project_id,'name',p.name,'revision',p.revision,'updatedAt',coalesce((select max(received.received_at) from public.nadi_revisions received where received.learner_id=p.learner_id and received.project_id=p.project_id),p.updated_at),'snapshotId',(select r.id from public.nadi_revisions r where r.learner_id=p.learner_id and r.project_id=p.project_id and r.revision=p.revision)) order by p.updated_at desc) from public.nadi_projects p where p.learner_id=p_learner_id),'[]'::jsonb));
end $$;
